function showScreen(key){
  Object.values(screens).forEach(s=>s.classList.remove("active"));
  screens[key].classList.add("active");
  if(els.gameHeader){
    els.gameHeader.classList.toggle("hidden-header",key==="start"||key==="rules");
  }
  window.scrollTo({top:0,behavior:"smooth"});
}

function tierFor(l){
  const avg=allKeys.reduce((s,k)=>s+l.stats[k],0)/allKeys.length;

  // Historical/current cards now use rarity as their broad power class.
  // Fictional cards are deliberately exempt: Mythic means unusual, not necessarily good.
  if(l.pack!=="Fictional & Legendary"){
    if(l.rarity==="Legendary")return "Elite";
    if(l.rarity==="Rare")return "Strong";
    if(l.rarity==="Uncommon")return "Solid";
    return avg>=68?"Capable":"Risky";
  }

  if(avg>=90)return "Elite";
  if(avg>=82)return "Strong";
  if(avg>=73)return "Solid";
  if(avg>=62)return "Risky";
  return "Disaster";
}

function powerClass(t){return t==="Elite"?"power-elite":t==="Disaster"?"power-disaster":""}
function rarityClass(r){return r.toLowerCase()}
function statBand(value){
  if(value>=100)return "90–100";
  const low=Math.floor(value/10)*10;
  return `${low}–${low+10}`;
}
function bandMidpoint(value){
  if(value>=100)return 95;
  return Math.floor(value/10)*10+5;
}
function packShort(pack){
  if(pack==="Conquerors & Generals")return "Conquerors";
  if(pack==="Presidents & Prime Ministers")return "Pres / PM";
  if(pack==="Infamous Leaders")return "Infamous";
  if(pack==="Current Leaders")return "Current";
  if(pack==="Kings & Queens")return "Monarchs";
  if(pack==="Fictional & Legendary")return "Fictional";
  return pack;
}

function hashString(str){
  let h=2166136261;
  for(let i=0;i<str.length;i++){
    h^=str.charCodeAt(i);
    h=Math.imul(h,16777619);
  }
  return h>>>0;
}

function fallbackPortrait(name,fictional=false){
  const h=hashString(name);
  const initials=name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join("");
  const hue=h%360;
  const bg=fictional?`hsl(${hue} 42% 18%)`:`hsl(${hue} 22% 20%)`;
  const stroke=fictional?`hsl(${hue} 60% 64%)`:`hsl(${hue} 26% 68%)`;
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400" viewBox="0 0 400 400"><rect width="400" height="400" fill="${bg}"/><circle cx="200" cy="170" r="86" fill="none" stroke="${stroke}" stroke-width="9"/><path d="M82 356c18-78 73-112 118-112s100 34 118 112" fill="none" stroke="${stroke}" stroke-width="14" stroke-linecap="round"/><text x="200" y="197" text-anchor="middle" font-family="Arial,sans-serif" font-size="74" font-weight="700" fill="${stroke}">${initials}</text></svg>`;
  return "data:image/svg+xml;charset=UTF-8,"+encodeURIComponent(svg);
}

async function loadPortrait(leader,img){
  const fallback=fallbackPortrait(leader.name,leader.fictional);
  img.src=fallback;
  if(leader.fictional||!leader.wiki)return;
  if(portraitCache.has(leader.wiki)){
    const u=portraitCache.get(leader.wiki);
    if(u)img.src=u;
    return;
  }
  try{
    const url=`https://en.wikipedia.org/w/api.php?action=query&format=json&origin=*&prop=pageimages&piprop=thumbnail&pithumbsize=360&titles=${encodeURIComponent(leader.wiki)}`;
    const res=await fetch(url);
    if(!res.ok)throw new Error("portrait request failed");
    const data=await res.json();
    const page=Object.values(data.query?.pages||{})[0];
    const src=page?.thumbnail?.source||null;
    portraitCache.set(leader.wiki,src);
    if(src)img.src=src;
  }catch(e){
    portraitCache.set(leader.wiki,null);
  }
}

function makeCountry(row){
  const h=hashString(row.name);
  let tier;
  if(tier5.has(row.name))tier=5;
  else if(tier4.has(row.name))tier=4;
  else if(microstates.has(row.name))tier=1;
  else tier=2+((h>>>3)%2);

  const base={1:58,2:64,3:69,4:75,5:81}[tier];
  let focus=[...focusPairs[h%focusPairs.length]];

  if(islandStates.has(row.name))focus=["logistics","adaptability"];
  else if(vastStates.has(row.name))focus=["logistics","administration"];
  else if(mountainStates.has(row.name))focus=["logistics","adaptability"];

  const req={};
  allKeys.forEach((key,i)=>{
    const off=((h>>>(i*4))%9)-4;
    req[key]=base+off;
  });

  focus.forEach(k=>req[k]+=7);
  if(tier===5){
    req.military+=3;
    req.logistics+=3;
    req.administration+=2;
  }
  if(islandStates.has(row.name))req.logistics+=3;
  if(vastStates.has(row.name))req.logistics+=3;

  allKeys.forEach(k=>req[k]=Math.max(48,Math.min(95,req[k])));
  return {...row,tier,focus,req};
}

const countries=countryRows.map(makeCountry);

function randomUnit(){
  if(globalThis.crypto?.getRandomValues){
    const a=new Uint32Array(1);
    crypto.getRandomValues(a);
    return a[0]/4294967296;
  }
  return Math.random();
}

function getPreviousAttemptNames(){
  try{
    const raw=localStorage.getItem("world193V36PreviousOffers");
    const names=raw?JSON.parse(raw):[];
    return new Set(Array.isArray(names)?names:[]);
  }catch(e){
    return new Set();
  }
}

function saveCurrentAttemptNames(){
  if(!usedNames.size)return;
  try{
    localStorage.setItem("world193V36PreviousOffers",JSON.stringify([...usedNames]));
  }catch(e){}
}

let previousAttemptNames=getPreviousAttemptNames();

function rollRarity(){
  const roll=randomUnit()*100;
  let running=0;
  for(const [rarity,chance] of rarityRollTable){
    running+=chance;
    if(roll<running)return rarity;
  }
  return "Common";
}

function randomFrom(array){
  if(!array.length)return null;
  return array[Math.floor(randomUnit()*array.length)];
}

function leaderFromRarity(rarity,excluded){
  const eligible=leaders.filter(l=>l.rarity===rarity&&!excluded.has(l.name));
  if(!eligible.length)return null;

  // Do not repeat somebody from the immediately previous attempt when there is
  // any unseen alternative in the same rarity bucket.
  const fresh=eligible.filter(l=>!previousAttemptNames.has(l.name));
  return randomFrom(fresh.length?fresh:eligible);
}

function rarityRolledLeader(excluded){
  // Roll the rarity first, then select a random person from that rarity.
  // Retry a different rarity only in the extremely unlikely event that the
  // selected bucket has been exhausted within the current attempt.
  for(let attempts=0;attempts<20;attempts++){
    const rarity=rollRarity();
    const leader=leaderFromRarity(rarity,excluded);
    if(leader)return leader;
  }

  const fallback=leaders.filter(l=>!excluded.has(l.name)&&!previousAttemptNames.has(l.name));
  return randomFrom(fallback.length?fallback:leaders.filter(l=>!excluded.has(l.name)));
}

function drawChoices(){
  const picks=[];
  const excluded=new Set(usedNames);
  while(picks.length<5){
    const l=rarityRolledLeader(excluded);
    if(!l)break;
    picks.push(l);
    excluded.add(l.name);
  }
  return picks;
}

function startDraft(){
  saveCurrentAttemptNames();
  previousAttemptNames=new Set(usedNames.size?[...usedNames]:[...getPreviousAttemptNames()]);
  squad=[];
  usedNames=new Set();
  currentRunSeed=Math.floor(randomUnit()*1e9);
  practiceMode=false;
  respinAvailable=true;
  updateRespinButton();
  renderSquad();
  nextRound();
  showScreen("draft");
}

function nextRound(){
  if(squad.length>=6){
    renderFinalSquad();
    showScreen("lock");
    return;
  }
  els.roundNumber.textContent=squad.length+1;
  currentChoices=drawChoices();
  currentChoices.forEach(l=>usedNames.add(l.name));
  renderChoices();
}

function updateRespinButton(){
  els.respinBtn.disabled=!respinAvailable;
  els.respinText.textContent=respinAvailable?"Respin (1)":"Respin Used";
  els.respinBtn.setAttribute("aria-label",respinAvailable?"Respin the current five leader choices. One use remaining.":"Respin already used this attempt.");
}

function respinChoices(){
  if(!respinAvailable||squad.length>=6)return;
  respinAvailable=false;
  currentChoices=drawChoices();
  currentChoices.forEach(l=>usedNames.add(l.name));
  updateRespinButton();
  renderChoices();
}

function scoutRows(l){
  return visibleKeys.map(k=>`<div class="scout-stat"><span>${labels[k]}</span><div class="mini-track"><div class="mini-fill" style="width:${bandMidpoint(l.stats[k])}%"></div></div><b>${statBand(l.stats[k])}</b></div>`).join("");
}

function renderChoices(){
  els.leaderChoices.innerHTML="";
  currentChoices.forEach((leader)=>{
    const tier=tierFor(leader);
    const card=document.createElement("article");
    card.className="leader-card";
    card.innerHTML=`<div class="card-top"><img class="portrait" alt="Portrait of ${leader.name}"><div class="badges"><span class="badge pack-badge">${packShort(leader.pack)}</span><span class="badge ${rarityClass(leader.rarity)}">${leader.rarity}</span><span class="badge ${powerClass(tier)}">${tier}</span></div></div><h3>${leader.name}</h3><div class="leader-meta">${leader.era} • ${leader.archetype}</div><p class="leader-blurb">${leader.blurb}</p><div class="scout-title">SCOUTED STAT RANGES</div>${scoutRows(leader)}<div class="trait-preview">${leader.traits.map(t=>`<span class="trait-chip">${t}</span>`).join("")}</div><div class="pick-hint">DRAFT THIS LEADER →</div>`;
    card.addEventListener("click",()=>draftLeader(leader));
    els.leaderChoices.appendChild(card);
    loadPortrait(leader,card.querySelector("img"));
  });
}

function draftLeader(leader){
  squad.push(leader);
  renderSquad();
  nextRound();
}

function renderSquad(){
  els.squadCount.textContent=`${squad.length} / 6`;
  els.squadSlots.innerHTML="";
  for(let i=0;i<6;i++){
    const slot=document.createElement("div");
    if(squad[i]){
      slot.className="squad-slot filled";
      slot.innerHTML=`<img class="slot-portrait" alt="${squad[i].name}"><div><strong>${squad[i].name}</strong><small>${packShort(squad[i].pack)} • ${squad[i].rarity} • ${tierFor(squad[i])}</small></div>`;
      loadPortrait(squad[i],slot.querySelector("img"));
    }else{
      slot.className="squad-slot";
      slot.textContent=`Pick ${i+1}`;
    }
    els.squadSlots.appendChild(slot);
  }
}

function renderFinalSquad(){
  els.finalSquad.innerHTML="";
  squad.forEach((leader,i)=>{
    const d=document.createElement("div");
    d.className="final-card";
    d.innerHTML=`<img alt="Portrait of ${leader.name}"><strong>${i+1}. ${leader.name}</strong><span>${packShort(leader.pack)} • ${leader.rarity} • ${tierFor(leader)}<br>${leader.traits.join(" • ")}</span>`;
    els.finalSquad.appendChild(d);
    loadPortrait(leader,d.querySelector("img"));
  });
}

function computeTeamProfile(){
  const weights=[.24,.21,.18,.15,.12,.10];
  const profile={};
  allKeys.forEach(key=>{
    const vals=squad.map(l=>l.stats[key]).sort((a,b)=>b-a);
    profile[key]=vals.reduce((sum,v,i)=>sum+v*weights[i],0);
  });

  const archetypes=squad.map(l=>l.archetype);
  const uniqueArchetypes=new Set(archetypes).size;
  let chemistry=Math.min(3,(uniqueArchetypes-2)*.7);

  const militaryHeavy=squad.filter(l=>l.stats.military>=90).length;
  const lowDip=squad.filter(l=>l.stats.diplomacy<50).length;
  const adminStrong=squad.filter(l=>l.stats.administration>=90).length;
  const dipStrong=squad.filter(l=>l.stats.diplomacy>=90).length;
  const logStrong=squad.filter(l=>l.stats.logistics>=88).length;
  const econStrong=squad.filter(l=>l.stats.economy>=88).length;

  if(militaryHeavy>=5)chemistry-=4.5;
  else if(militaryHeavy>=4)chemistry-=2.5;
  if(lowDip>=3)chemistry-=3;
  if(adminStrong>=2&&militaryHeavy>=2)chemistry+=1.5;
  if(dipStrong>=2)chemistry+=1;
  if(logStrong>=2)chemistry+=1.5;
  if(econStrong>=2)chemistry+=1;

  const traits=new Set(squad.flatMap(l=>l.traits));
  if(traits.has("Logistics Master"))profile.logistics+=2;
  if(traits.has("Royal Road"))profile.logistics+=1.5;
  if(traits.has("Gold Reserves"))profile.economy+=2;
  if(traits.has("Prescience")){profile.logistics+=3;profile.adaptability+=3;}
  if(traits.has("Rule of Fear")){profile.military+=2;profile.administration+=2;profile.diplomacy-=4;chemistry-=1.5;}
  if(traits.has("Bought the Throne"))chemistry-=2;
  if(traits.has("Coalition Builder")||traits.has("Rebel Coalition"))profile.diplomacy+=1.5;
  if(traits.has("Road Network"))profile.logistics+=1.5;
  if(traits.has("Blue-Water Reach"))profile.logistics+=1.2;

  allKeys.forEach(k=>profile[k]=Math.max(0,Math.min(100,profile[k]+chemistry)));
  const minStat=Math.min(...allKeys.map(k=>profile[k]));
  return {profile,chemistry,uniqueArchetypes,minStat};
}

function seededNoise(seed,index){
  const x=Math.sin(seed*.000001+index*12.9898)*43758.5453;
  return((x-Math.floor(x))-.5)*1.6;
}

function evaluateCountry(country,idx,team,seed){
  let score=0,totalWeight=0;
  allKeys.forEach(key=>{
    const weight=country.focus.includes(key)?1.8:1;
    score+=(team.profile[key]-country.req[key])*weight;
    totalWeight+=weight;
  });
  score/=totalWeight;
  score+=seededNoise(seed,idx);

  const focusAverage=country.focus.reduce((s,k)=>s+team.profile[k],0)/country.focus.length;
  const reqFocus=country.focus.reduce((s,k)=>s+country.req[k],0)/country.focus.length;
  score+=(focusAverage-reqFocus)*.30;

  if(team.minStat<67)score-=(67-team.minStat)*.18;

  return {country,margin:score,win:score>=8.7};
}

function simulateCampaign(practice=false){
  practiceMode=practice;
  currentRunSeed=Math.floor(randomUnit()*1e9);
  const team=computeTeamProfile();
  const results=countries.map((c,i)=>evaluateCountry(c,i,team,currentRunSeed));
  revealResults(results,team,practice);
}

function renderEmptyWorld(){
  els.regionSummary.innerHTML=REGION_ORDER.map(region=>{
    const total=countries.filter(c=>c.region===region).length;
    return `<div class="region-chip" data-region-summary="${region}"><span>${region}</span><strong>0–0</strong><small class="muted-total"> / ${total}</small></div>`;
  }).join("");

  els.worldResults.innerHTML="";
  REGION_ORDER.forEach(region=>{
    const section=document.createElement("section");
    section.className="world-region";
    const regionCountries=countries.filter(c=>c.region===region);
    section.innerHTML=`<div class="world-region-head"><h3>${region}</h3><span class="world-region-record" data-region-record="${region}">0–0</span></div><div class="country-grid">${regionCountries.map(c=>`<div class="country-tile" data-country-index="${countries.indexOf(c)}"><span class="country-name">${c.name}</span><span class="country-mark">•</span></div>`).join("")}</div>`;
    els.worldResults.appendChild(section);
  });
}

function updateRegionDisplay(region,wins,losses){
  const summary=els.regionSummary.querySelector(`[data-region-summary="${region}"] strong`);
  const header=els.worldResults.querySelector(`[data-region-record="${region}"]`);
  if(summary)summary.textContent=`${wins}–${losses}`;
  if(header)header.textContent=`${wins}–${losses}`;
}

async function revealResults(results,team,practice){
  showScreen("result");
  els.recordReveal.classList.remove("perfect");
  els.recordReveal.textContent="0–0";
  els.resultTagline.textContent=practice?"Practice world simulation...":"The world campaign is being revealed...";
  els.postGame.classList.add("hidden");
  renderEmptyWorld();

  let wins=0,losses=0;
  const regionRecords=Object.fromEntries(REGION_ORDER.map(r=>[r,{wins:0,losses:0}]));

  for(let i=0;i<results.length;i+=5){
    const batch=results.slice(i,i+5);
    batch.forEach((r,j)=>{
      const idx=i+j;
      if(r.win){wins++;regionRecords[r.country.region].wins++;}
      else{losses++;regionRecords[r.country.region].losses++;}
      const tile=els.worldResults.querySelector(`[data-country-index="${idx}"]`);
      tile.classList.add("revealed",r.win?"win":"loss");
      tile.querySelector(".country-mark").textContent=r.win?"✓":"✕";
      updateRegionDisplay(r.country.region,regionRecords[r.country.region].wins,regionRecords[r.country.region].losses);
    });
    els.recordReveal.textContent=`${wins}–${losses}`;
    await wait(55);
  }

  if(!practice)updateBest(wins);

  const finalRecord=`${wins}–${losses}`;
  if(wins===193){
    els.recordReveal.classList.add("perfect");
    els.resultTagline.textContent=practice?"193–0 in practice. Now draft it for real.":"PERFECT WORLD RUN. You actually went 193–0.";
  }else if(wins>=190){
    els.resultTagline.textContent=`${finalRecord}. Absolute heartbreak — you were within sight of perfection.`;
  }else if(wins>=180){
    els.resultTagline.textContent=`${finalRecord}. An elite world campaign, but a few matchups found the cracks.`;
  }else if(wins>=160){
    els.resultTagline.textContent=`${finalRecord}. Strong globally, but not balanced enough for the hardest tests.`;
  }else if(wins>=120){
    els.resultTagline.textContent=`${finalRecord}. Respectable reach, with major weaknesses exposed.`;
  }else{
    els.resultTagline.textContent=`${finalRecord}. This squad was nowhere near world-conquest ready.`;
  }

  renderAnalysis(results,team);
  renderLeaderReveal();
  els.postGame.classList.remove("hidden");
}

function renderAnalysis(results,team){
  const statsHtml=Object.entries(team.profile).map(([key,val])=>`<div class="stat-row"><span>${labels[key]}</span><div class="stat-bar"><div class="stat-fill" style="width:${bandMidpoint(val)}%"></div></div><strong>${statBand(val)}</strong></div>`).join("");

  const weakest=Object.entries(team.profile).sort((a,b)=>a[1]-b[1])[0];
  const strongest=Object.entries(team.profile).sort((a,b)=>b[1]-a[1])[0];

  const leaderScores=squad.map(l=>({
    leader:l,
    average:allKeys.reduce((sum,key)=>sum+l.stats[key],0)/allKeys.length
  })).sort((a,b)=>a.average-b.average);

  const weakestLeader=leaderScores[0];

  const notes=[];

  if(team.chemistry>=4){
    notes.push(`Excellent roster construction produced a +${team.chemistry.toFixed(1)} chemistry modifier.`);
  }else if(team.chemistry<0){
    notes.push(`Roster conflicts produced a ${team.chemistry.toFixed(1)} chemistry modifier.`);
  }else{
    notes.push(`Your chemistry modifier was +${team.chemistry.toFixed(1)}.`);
  }

  notes.push(`Best team dimension: ${labels[strongest[0]]} (${statBand(strongest[1])}).`);
  notes.push(`Weakest team dimension: ${labels[weakest[0]]} (${statBand(weakest[1])}).`);
  notes.push(`${weakestLeader.leader.name} held the team back most, with the lowest overall six-stat profile in the squad.`);

  els.analysisPanel.innerHTML=`<div class="analysis-grid"><div><h3>Full squad profile</h3>${statsHtml}</div><div><h3>World Campaign Analysis</h3><ul class="note-list">${notes.map(n=>`<li>${n}</li>`).join("")}</ul></div></div>`;
}

function renderLeaderReveal(){
  els.leaderReveal.innerHTML=`<h3>Squad stat ranges</h3><div class="reveal-grid">${squad.map(l=>`<div class="reveal-person"><strong>${l.name}</strong><small>${packShort(l.pack)}</small>${allKeys.map(k=>`<div class="tiny-stat"><span>${labels[k]}</span><b>${statBand(l.stats[k])}</b></div>`).join("")}</div>`).join("")}</div>`;
}

function updateBest(wins){
  const oldBest=Number(localStorage.getItem("world193V3Best")||0);
  const best=Math.max(oldBest,wins);
  localStorage.setItem("world193V3Best",best);
  els.bestRecord.textContent=`${best}–${193-best}`;
}

function wait(ms){return new Promise(resolve=>setTimeout(resolve,ms))}

